#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
typedef pair<int, int> PI;
const LL MOD = 1000000009;

LL modExp(LL base, LL exp, LL m = MOD) {
    LL result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % m;
        base = (base * base) % m;
        exp >>= 1;
    }
    return result;
}

struct Modular {
    LL val;
    Modular() : val(0) {}
    Modular(LL v) {
        val = v % MOD;
        if (val < 0) val += MOD;
    }
    operator int() const { return (int)val; }
    Modular& operator+=(const Modular& other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }
    Modular& operator-=(const Modular& other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }
    Modular& operator*=(const Modular& other) {
        val = (val * other.val) % MOD;
        return *this;
    }
    friend Modular operator+(Modular a, const Modular& b) { return a += b; }
    friend Modular operator-(Modular a, const Modular& b) { return a -= b; }
    friend Modular operator*(Modular a, const Modular& b) { return a *= b; }
    friend Modular operator^(Modular a, LL n) {
        Modular res(1);
        while (n > 0) {
            if (n & 1) res *= a;
            a *= a;
            n >>= 1;
        }
        return res;
    }
};

LL inv(LL a, LL p) {
    if (a == 1) return 1;
    return (1 - p * inv(p % a, a)) / a + p;
}

const int MAXN = 262144;
Modular fact[MAXN], inv_fact[MAXN];

void init_factorials() {
    fact[0] = Modular(1);
    for (int i = 1; i < MAXN; i++) {
        fact[i] = fact[i - 1] * Modular(i);
    }
    inv_fact[MAXN - 1] = Modular(1) / fact[MAXN - 1];
    for (int i = MAXN - 2; i >= 0; i--) {
        inv_fact[i] = inv_fact[i + 1] * Modular(i + 1);
    }
}

Modular comb(int a, int b) {
    if (a < 0 || b < 0 || a < b) return Modular(0);
    return fact[a] * inv_fact[b] * inv_fact[a - b];
}

pair<Modular, Modular> multiply_pairs(pair<Modular, Modular> a, pair<Modular, Modular> b) {
    return {a.first * b.first, a.second * b.first + a.first * b.second};
}

pair<Modular, Modular> add_pairs(pair<Modular, Modular> a, pair<Modular, Modular> b) {
    return {a.first + b.first, a.second + b.second};
}

pair<Modular, Modular> dp[501];
bool used[501];

void prepare() {
    init_factorials();
    dp[0] = {Modular(1), Modular(0)};
    dp[1] = {Modular(2), Modular(0)};
    for (int n = 2; n <= 500; n++) {
        for (int j = 0; j < n; j++) {
            Modular cnt = Modular(n + 1);
            Modular sum = Modular(0);
            for (int k = 0; k < n; k++) {
                sum += abs(j - k);
            }
            auto left = dp[j];
            auto right = dp[n - 1 - j];
            auto x = multiply_pairs(left, right);
            x.first *= comb(n - 1, j);
            x.second *= comb(n - 1, j);
            x.first *= cnt;
            x.second *= cnt + sum;
            dp[n] = add_pairs(dp[n], x);
        }
    }
}

pair<Modular, Modular> dp2[502][501];

void execute() {
    int n, m; cin >> n >> m;
    prepare();
    for (int i = 0; i <= n; i++) {
        for (int k = 0; k <= m; k++) {
            dp2[i][k] = {Modular(0), Modular(0)};
        }
    }
    dp2[0][0] = {Modular(1), Modular(0)};
    for (int i = 0; i < n; i++) {
        for (int k = 0; k <= m; k++) {
            if (dp2[i][k].first.val == 0 && dp2[i][k].second.val == 0) continue;
            for (int j = i; j < n; j++) {
                int ni = j + 2;
                if (ni > n) ni = n;
                int nk = k + j - i + 1;
                if (nk <= m) {
                    auto x = multiply_pairs(dp2[i][k], dp[j - i + 1]);
                    x.first *= comb(nk, k);
                    x.second *= comb(nk, k);
                    dp2[ni][nk] = add_pairs(dp2[ni][nk], x);
                }
            }
            if (i + 1 <= n && k <= m) {
                dp2[i + 1][k] = add_pairs(dp2[i + 1][k], dp2[i][k]);
            }
        }
    }
    cout << (int)dp2[n][m].second << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    execute();
    return 0;
}
