import java.util.Scanner;

public class Main {
    static final long MOD = 1000000009L;
    static final int MAXN = 262144;
    static Modular[] fact = new Modular[MAXN];
    static Modular[] invFact = new Modular[MAXN];
    static Pair<Modular, Modular>[] dp = new Pair[501];
    static boolean[] used = new boolean[501];
    static Pair<Modular, Modular>[][] dp2 = new Pair[502][501];

    static class Modular {
        long val;

        Modular() {
            this.val = 0;
        }

        Modular(long v) {
            this.val = v % MOD;
            if (this.val < 0) this.val += MOD;
        }

        Modular add(Modular other) {
            long res = this.val + other.val;
            if (res >= MOD) res -= MOD;
            return new Modular(res);
        }

        Modular subtract(Modular other) {
            long res = this.val - other.val;
            if (res < 0) res += MOD;
            return new Modular(res);
        }

        Modular multiply(Modular other) {
            long res = (this.val * other.val) % MOD;
            return new Modular(res);
        }

        Modular pow(long n) {
            Modular res = new Modular(1);
            Modular base = this;
            while (n > 0) {
                if ((n & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                n >>= 1;
            }
            return res;
        }

        Modular inverse() {
            // Fermat's little theorem since MOD is prime
            return this.pow(MOD - 2);
        }
    }

    static class Pair<A, B> {
        A first;
        B second;

        Pair(A a, B b) {
            this.first = a;
            this.second = b;
        }
    }

    static long inv(long a, long p) {
        if (a == 1) return 1;
        return (1 - p * inv(p % a, a)) / a + p;
    }

    static void initFactorials() {
        fact[0] = new Modular(1);
        for (int i = 1; i < MAXN; i++) {
            fact[i] = fact[i - 1].multiply(new Modular(i));
        }
        invFact[MAXN - 1] = fact[MAXN - 1].inverse();
        for (int i = MAXN - 2; i >= 0; i--) {
            invFact[i] = invFact[i + 1].multiply(new Modular(i + 1));
        }
    }

    static Modular comb(int a, int b) {
        if (a < 0 || b < 0 || a < b) return new Modular(0);
        return fact[a].multiply(invFact[b]).multiply(invFact[a - b]);
    }

    static Pair<Modular, Modular> multiplyPairs(Pair<Modular, Modular> a, Pair<Modular, Modular> b) {
        return new Pair<>(a.first.multiply(b.first), a.second.multiply(b.first).add(a.first.multiply(b.second)));
    }

    static Pair<Modular, Modular> addPairs(Pair<Modular, Modular> a, Pair<Modular, Modular> b) {
        return new Pair<>(a.first.add(b.first), a.second.add(b.second));
    }

    static void prepare() {
        initFactorials();
        dp[0] = new Pair<>(new Modular(1), new Modular(0));
        dp[1] = new Pair<>(new Modular(2), new Modular(0));
        for (int n = 2; n <= 500; n++) {
            Pair<Modular, Modular> sumPair = new Pair<>(new Modular(0), new Modular(0));
            for (int j = 0; j < n; j++) {
                Modular cnt = new Modular(n + 1);
                Modular sum = new Modular(0);
                for (int k = 0; k < n; k++) {
                    sum = sum.add(new Modular(Math.abs(j - k)));
                }
                Pair<Modular, Modular> left = dp[j];
                Pair<Modular, Modular> right = dp[n - 1 - j];
                Pair<Modular, Modular> x = multiplyPairs(left, right);
                x = new Pair<>(x.first.multiply(comb(n - 1, j)), x.second.multiply(comb(n - 1, j)));
                x = new Pair<>(x.first.multiply(cnt), x.second.multiply(cnt).add(sum.multiply(cnt)));
                sumPair = addPairs(sumPair, x);
            }
            dp[n] = sumPair;
        }
    }

    static void execute(Scanner sc) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        prepare();
        for (int i = 0; i <= n; i++) {
            for (int k = 0; k <= m; k++) {
                dp2[i][k] = new Pair<>(new Modular(0), new Modular(0));
            }
        }
        dp2[0][0] = new Pair<>(new Modular(1), new Modular(0));
        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= m; k++) {
                if (dp2[i][k].first.val == 0 && dp2[i][k].second.val == 0) continue;
                for (int j = i; j < n; j++) {
                    int ni = j + 2;
                    if (ni > n) ni = n;
                    int nk = k + j - i + 1;
                    if (nk <= m) {
                        Pair<Modular, Modular> x = multiplyPairs(dp2[i][k], dp[j - i + 1]);
                        x = new Pair<>(x.first.multiply(comb(nk, k)), x.second.multiply(comb(nk, k)));
                        dp2[ni][nk] = addPairs(dp2[ni][nk], x);
                    }
                }
                if (i + 1 <= n && k <= m) {
                    dp2[i + 1][k] = addPairs(dp2[i + 1][k], dp2[i][k]);
                }
            }
        }
        System.out.println(dp2[n][m].second.val);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        execute(sc);
        sc.close();
    }
}

